import org.junit.jupiter.api.Test;

class ScalarExtensionRegressionTest {
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void malformedNumbersRaiseEvaluationErrors() {
		for (Function function : List.of(new Round(), new Trunc(), new Sign())) {
			for (CoreDatatype.XSD type : List.of(CoreDatatype.XSD.INTEGER, CoreDatatype.XSD.DECIMAL,
					CoreDatatype.XSD.FLOAT, CoreDatatype.XSD.DOUBLE)) {
				Literal value = VF.createLiteral("bad", type);
				assertThatThrownBy(() -> function.evaluate(VF, value)).as(function.getURI() + type)
						.isInstanceOf(ValueExprEvaluationException.class);
			}
		}
		assertThatThrownBy(() -> new DecimalFormat().evaluate(VF,
				VF.createLiteral("bad", CoreDatatype.XSD.DECIMAL), VF.createLiteral("0.00")))
						.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new GenerateSeries().evaluate(VF,
				VF.createLiteral("bad", CoreDatatype.XSD.INTEGER), VF.createLiteral(2)))
						.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void integerNarrowingChecksTheOriginalExactValue() {
		Left function = new Left();
		for (BigInteger n : List.of(BigInteger.ONE.shiftLeft(64).add(BigInteger.ONE),
				BigInteger.ONE.shiftLeft(64).negate().subtract(BigInteger.ONE),
				BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE))) {
			assertThatThrownBy(() -> FunctionArgs.toLong(function, VF.createLiteral(n)))
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> FunctionArgs.toInt(function, VF.createLiteral(n)))
					.isInstanceOf(ValueExprEvaluationException.class);
		}
		assertThat(FunctionArgs.toLong(function, VF.createLiteral(BigInteger.valueOf(Long.MIN_VALUE))))
				.isEqualTo(Long.MIN_VALUE);
		assertThat(FunctionArgs.toLong(function, VF.createLiteral(BigInteger.valueOf(Long.MAX_VALUE))))
				.isEqualTo(Long.MAX_VALUE);
	}

	@Test
	void xpathPowRetainsSpecialValuesAndIntegerExponentParity() {
		XPathPow pow = new XPathPow();
		assertThat(pow.evaluate(VF, VF.createLiteral(1), VF.createLiteral(Double.NaN)).doubleValue()).isEqualTo(1);
		for (double infinity : new double[] { Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY }) {
			for (int base : new int[] { -1, 1 }) {
				assertThat(pow.evaluate(VF, VF.createLiteral(base), VF.createLiteral(infinity)).doubleValue())
						.isEqualTo(1);
			}
		}
		for (BigInteger n : List.of(new BigInteger("9007199254740993"),
				new BigInteger("-9007199254740993"), BigInteger.ONE.shiftLeft(100).add(BigInteger.ONE))) {
			assertThat(pow.evaluate(VF, VF.createLiteral(-1), VF.createLiteral(n)).doubleValue()).isEqualTo(-1);
		}
		assertThat(pow.evaluate(VF, VF.createLiteral(-1), VF.createLiteral(BigInteger.ONE.shiftLeft(100)))
				.doubleValue()).isEqualTo(1);
	}

	@Test
	void regexCacheKeepsFlagsSeparateFromPatternContents() {
		String pattern = "scalarRegressionUniquePattern";
		RegexCache.compile("i\u0000" + pattern, null);
		assertThat(RegexCache.compile(pattern, "i").matcher(pattern.toUpperCase(Locale.ROOT)).matches())
				.isTrue();
		assertThat(RegexCache.compile("i\u0000" + pattern, "").matcher("i\u0000" + pattern).matches()).isTrue();
	}

	@Test
	void negativeSplitPartCountsTheExistingFieldsFromTheEnd() {
		for (String[] input : List.of(new String[] { "a|||b", "||" }, new String[] { "aaaaa", "aa" },
				new String[] { "a😀😀😀b", "😀😀" }, new String[] { "a::b::", "::" })) {
			List<String> parts = Split.split(input[0], input[1]);
			for (int i = 0; i < parts.size(); i++) {
				assertThat(new SplitPart().evaluate(VF, VF.createLiteral(input[0]), VF.createLiteral(input[1]),
						VF.createLiteral(i - parts.size())).getLabel()).isEqualTo(parts.get(i));
			}
		}
	}

	@Test
	void extractedArrayPartsKeepLanguageAndDirection() {
		for (Literal source : List.of(VF.createLiteral("a,b", "en"),
				VF.createLiteral("a,b", "ar", Literal.BaseDirection.RTL))) {
			Literal result = new Split().evaluate(VF, source, VF.createLiteral(","));
			List<?> parts = (List<?>) JsonSupport.parse(result.getLabel());
			assertThat(JsonSupport.toValue(parts.get(0), VF)).isEqualTo(sameKind("a", source));
			assertThat(JsonSupport.toValue(parts.get(1), VF)).isEqualTo(sameKind("b", source));
			Literal matches = new RegexpExtractAll().evaluate(VF, source, VF.createLiteral("[a-z]"));
			List<?> extracted = (List<?>) JsonSupport.parse(matches.getLabel());
			assertThat(JsonSupport.toValue(extracted.get(0), VF)).isEqualTo(sameKind("a", source));
		}
	}

	@Test
	void extractedTuplePartsKeepLanguageAndDirection() {
		Literal source = VF.createLiteral("a,b", "ar", Literal.BaseDirection.RTL);
		for (TupleFunction function : List.of(new SplitTupleFunction(), new RegexpExtractAllTupleFunction())) {
			Literal delimiter = VF.createLiteral(function instanceof SplitTupleFunction ? "," : "[a-z]");
			List<Value> values = new ArrayList<>();
			try (var rows = function.evaluate(VF, source, delimiter)) {
				while (rows.hasNext()) {
					values.add(rows.next().get(0));
				}
			}
			assertThat(values).containsExactly(sameKind("a", source), sameKind("b", source));
		}
	}

	@Test
	void repeatRejectsOverflowBeforeAllocatingOrNarrowing() {
		for (long count : new long[] { Long.MAX_VALUE, 1L << 62, 1L << 32 }) {
			assertThatThrownBy(() -> new Repeat().evaluate(VF, VF.createLiteral("ab"), VF.createLiteral(count)))
					.isInstanceOf(ValueExprEvaluationException.class);
		}
		assertThat(new Repeat().evaluate(VF, VF.createLiteral("😀", "en"), VF.createLiteral(3)))
				.isEqualTo(VF.createLiteral("😀😀😀", "en"));
	}

	@Test
	void rightHandlesTheMostNegativeLength() {
		assertThat(new Right().evaluate(VF, VF.createLiteral("a😀b", "en"), VF.createLiteral(Integer.MIN_VALUE)))
				.isEqualTo(VF.createLiteral("", "en"));
		assertThat(new Right().evaluate(VF, VF.createLiteral("a😀b"), VF.createLiteral(-1)))
				.isEqualTo(VF.createLiteral("😀b"));
	}

	@Test
	void hmacAcceptsEmptyKeysForEverySupportedAlgorithm() {
		Hmac hmac = new Hmac();
		assertThat(hmac.evaluate(VF, VF.createLiteral("hello"), VF.createLiteral("")).getLabel())
				.isEqualTo("4352b26e33fe0d769a8922a6ba29004109f01688e26acc9e6cb347e5a5afc4da");
		for (String algorithm : List.of("md5", "sha1", "sha224", "sha256", "sha384", "sha512")) {
			for (String message : List.of("", "hello", "😀")) {
				assertThat(
						hmac.evaluate(VF, VF.createLiteral(message), VF.createLiteral(""), VF.createLiteral(algorithm)))
								.isEqualTo(hmac.evaluate(VF, VF.createLiteral(message),
										VF.createLiteral("00", CoreDatatype.XSD.HEXBINARY),
										VF.createLiteral(algorithm)));
			}
		}
	}

	private static Literal sameKind(String label, Literal source) {
		return VF.createLiteral(label, source.getLanguage().orElseThrow(), source.getBaseDirection());
	}
}
